)

mapper.select:
SELECT * FROM mcp_server WHERE active = 1 AND (is_public = 1 OR creator = #{currentUsername})
AND (name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
AND type = #{type}
ORDER BY status DESC, update_time DESC
